-- Stamps with the emblem and wordmark centred in the inner circle, with even space around them.
-- Only replaces the stamps seeded by 006, never an uploaded one.
UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'DEXEL' AND t.seal = 'data:image/svg+xml;base64,';

UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'ARTXEL' AND t.seal = 'data:image/svg+xml;base64,';
